     1	package hotel.reservations;
     2	
     3	import hotel.documents.ReservationReceipt;
     4	import hotel.rooms.Room;
     5	import hotel.rooms.Rooms;
     6	import java.math.BigDecimal;
     7	import java.util.List;
     8	
     9	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    10	public final class ReservationService {
    11	
    12	    private final Rooms rooms;
    13	    private final ReservationStore store;
    14	    private final PriceCalculator priceCalculator;
    15	    private final List<ReservationListener> listeners;
    16	
    17	    public ReservationService(
    18	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator,
    19	            List<ReservationListener> listeners) {
    20	        this.rooms = rooms;
    21	        this.store = store;
    22	        this.priceCalculator = priceCalculator;
    23	        this.listeners = List.copyOf(listeners);
    24	    }
    25	
    26	    public synchronized Reservation create(NewReservation request) {
    27	        if (!request.checkOut().isAfter(request.checkIn())) {
    28	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    29	        }
    30	        if (request.guests() < 1) {
    31	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    32	        }
    33	        Room room = rooms.find(request.roomNumber())
    34	                .orElseThrow(() -> new HotelException(
    35	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    36	        if (request.guests() > room.capacity()) {
    37	            throw new HotelException(
    38	                    ErrorCode.CAPACITY_EXCEEDED,
    39	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    40	        }
    41	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
    42	            throw new HotelException(
    43	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    44	        }
    45	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
    46	        return store.add(request, price);
    47	    }
    48	
    49	    public Reservation find(long reservationId) {
    50	        return store.find(reservationId)
    51	                .orElseThrow(() -> new HotelException(
    52	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    53	    }
    54	
    55	    /** The guest paid: the reservation is confirmed and the listeners are told. */
    56	    public synchronized Reservation confirm(long reservationId) {
    57	        Reservation reservation = find(reservationId);
    58	        if (reservation.status() != ReservationStatus.PENDING) {
    59	            throw notAllowed(reservation, "confirm");
    60	        }
    61	        reservation.confirmPayment();
    62	        store.update(reservation);
    63	        listeners.forEach(listener -> listener.confirmed(reservation));
    64	        return reservation;
    65	    }
    66	
    67	    /**
    68	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    69	     * reservation was never paid, so nothing comes back).
    70	     */
    71	    public synchronized Reservation cancel(long reservationId) {
    72	        Reservation reservation = find(reservationId);
    73	        if (reservation.status() != ReservationStatus.PENDING
    74	                && reservation.status() != ReservationStatus.CONFIRMED) {
    75	            throw notAllowed(reservation, "cancel");
    76	        }
    77	        ReservationStatus previousStatus = reservation.status();
    78	        BigDecimal refund = switch (reservation.ratePlan()) {
    79	            case STANDARD -> reservation.amountPaid();
    80	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
    81	        };
    82	        reservation.cancel(refund);
    83	        store.update(reservation);
    84	        listeners.forEach(listener -> listener.cancelled(reservation, previousStatus));
    85	        return reservation;
    86	    }
    87	
    88	    public synchronized Reservation checkIn(long reservationId) {
    89	        Reservation reservation = find(reservationId);
    90	        if (reservation.status() != ReservationStatus.CONFIRMED) {
    91	            throw notAllowed(reservation, "check in");
    92	        }
    93	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
    94	        store.update(reservation);
    95	        return reservation;
    96	    }
    97	
    98	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
    99	    public synchronized ReservationReceipt checkOut(long reservationId) {
   100	        Reservation reservation = find(reservationId);
   101	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   102	            throw notAllowed(reservation, "check out");
   103	        }
   104	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   105	        store.update(reservation);
   106	        return new ReservationReceipt(reservation, roomOf(reservation));
   107	    }
   108	
   109	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   110	    public ReservationReceipt receiptCopy(long reservationId) {
   111	        Reservation reservation = find(reservationId);
   112	        if (!reservation.isPaid()) {
   113	            throw notAllowed(reservation, "issue a receipt for");
   114	        }
   115	        return new ReservationReceipt(reservation, roomOf(reservation));
   116	    }
   117	
   118	    private Room roomOf(Reservation reservation) {
   119	        return rooms.find(reservation.roomNumber()).orElseThrow();
   120	    }
   121	
   122	    private static HotelException notAllowed(Reservation reservation, String operation) {
   123	        return new HotelException(
   124	                ErrorCode.OPERATION_NOT_ALLOWED,
   125	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
   126	    }
   127	}
