    67	                        rows.getString("subject"),
    68	                        rows.getString("body")));
    69	            }
    70	            return messages;
    71	        } catch (SQLException failure) {
    72	            throw new IllegalStateException("could not read the sent messages", failure);
    73	        }
    74	    }
    75	}

