    @Test
    void confirmingTellsHousekeepingAndFinance() {
        Reservation reservation = service.create(stay(201, "2027-03-10", "2027-03-12", 2, RatePlan.STANDARD));

        service.confirm(reservation.id());

        Message housekeeping = sentMessages.all().get(1);
        assertEquals("governanca@x.com", housekeeping.to());
        assertEquals("Reserva confirmada - quarto 201", housekeeping.subject());
        assertTrue(housekeeping.body().contains("Entrada: 10/03/2027"));
        assertTrue(housekeeping.body().contains("Saída: 12/03/2027"));
        assertTrue(housekeeping.body().contains("Hóspedes: 2"));
        Message finance = sentMessages.all().get(2);
        assertEquals("financeiro@x.com", finance.to());
        assertEquals("Pagamento recebido - reserva " + reservation.id(), finance.subject());
        assertTrue(finance.body().contains("R$ "));
    }

    @Test
    void cancellingAConfirmedReservationTellsHousekeepingAndFinanceOfTheRefund() {
        Reservation reservation = service.create(stay(201, "2027-03-10", "2027-03-12", 2, RatePlan.STANDARD));
        service.confirm(reservation.id());

        service.cancel(reservation.id());

        List<Message> sent = sentMessages.all();
        assertEquals(5, sent.size());
        assertEquals("Reserva cancelada - quarto 201", sent.get(3).subject());
        assertTrue(sent.get(3).body().contains("10/03/2027"));
        assertTrue(sent.get(3).body().contains("12/03/2027"));
        assertEquals("Reembolso - reserva " + reservation.id(), sent.get(4).subject());
        assertEquals("financeiro@x.com", sent.get(4).to());
    }

